const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "sqlite",
  "inlineSchema": "// WebRocz Agency OS — data model\n// SQLite for dev; swap datasource provider to \"postgresql\" for production.\n// Note: SQLite doesn't support Prisma enums, so status/role/service are strings\n// constrained by TypeScript constants in src/lib/domain.ts.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\nmodel User {\n  id           String   @id @default(cuid())\n  name         String\n  role         String // SUPER_ADMIN | AM_HEAD | ACCOUNT_MANAGER | SEO_HEAD | SEO | DESIGNER | EDITOR\n  email        String?  @unique\n  phone        String?\n  passwordHash String?\n  active       Boolean  @default(true)\n  createdAt    DateTime @default(now())\n\n  managedClients   Client[]       @relation(\"AccountManager\")\n  assignments      Assignment[]\n  updates          WorkUpdate[]\n  devProjects      DevProject[]   @relation(\"DevAssignee\")\n  timeSessions     TimeSession[]\n  tasksAssigned    Task[]         @relation(\"TaskAssigner\")\n  tasksReceived    Task[]         @relation(\"TaskAssignee\")\n  creativeTasks    CreativeTask[] @relation(\"CreativeAssignee\")\n  creativeAssigned CreativeTask[] @relation(\"CreativeAssigner\")\n  salesLeads       Lead[]         @relation(\"LeadOwner\")\n  shoots           Shoot[]        @relation(\"ShootAssignee\")\n  shootRequests    Shoot[]        @relation(\"ShootRequester\")\n}\n\nmodel Task {\n  id           String   @id @default(cuid())\n  title        String\n  detail       String   @default(\"\")\n  assignedById String\n  assignedBy   User     @relation(\"TaskAssigner\", fields: [assignedById], references: [id], onDelete: Cascade)\n  assignedToId String\n  assignedTo   User     @relation(\"TaskAssignee\", fields: [assignedToId], references: [id], onDelete: Cascade)\n  clientId     String?\n  client       Client?  @relation(fields: [clientId], references: [id], onDelete: SetNull)\n  priority     String   @default(\"MEDIUM\") // HIGH | MEDIUM | LOW\n  status       String   @default(\"TODO\") // TODO | IN_PROGRESS | DONE\n  dueDate      String   @default(\"\")\n  seen         Boolean  @default(false) // has the assignee opened it\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([assignedToId])\n  @@index([assignedById])\n  @@index([status])\n}\n\nmodel TimeSession {\n  id        String    @id @default(cuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  date      String // \"2026-08-29\" (local day the session started)\n  startedAt DateTime  @default(now())\n  endedAt   DateTime?\n  seconds   Int       @default(0) // filled on clock-out\n  note      String    @default(\"\")\n\n  @@index([userId])\n  @@index([date])\n}\n\nmodel Client {\n  id                 String   @id @default(cuid())\n  code               String   @unique // CLI-1000\n  name               String\n  website            String?\n  industry           String? // Real Estate, Healthcare, ...\n  monthlyRetainer    Int      @default(0) // INR / month\n  googleBudget       Int      @default(0) // monthly Google Ads budget (INR)\n  // --- SEO master fields (mirror the SEO team's Google Sheet) ---\n  seoPriority        String   @default(\"\") // A | B | C\n  seoScheduleDays    String   @default(\"\") // \"Mon, Wed, Fri\" / \"Daily 8 X 25 Days\"\n  blogTarget         Int      @default(8) // blogs / month\n  backlinkTarget     Int      @default(0) // backlinks / month\n  keywordTarget      Int      @default(0) // keywords tracked\n  gscLink            String   @default(\"\") // Google Search Console URL\n  gaLink             String   @default(\"\") // Google Analytics URL\n  domainAuthority    Int      @default(0) // DA (client website)\n  pocName            String?\n  pocMobile          String?\n  pocEmail           String?\n  onboardDate        DateTime @default(now())\n  renewalDate        String   @default(\"\") // \"2026-12-01\" — contract renewal\n  status             String   @default(\"ACTIVE\") // ACTIVE | ON_HOLD | UPCOMING\n  // --- Billing / GST ---\n  gstApplicable      Boolean  @default(true) // whether invoices for this client carry GST\n  gstRate            Int      @default(18) // GST % applied when applicable\n  gstin              String   @default(\"\") // client's GSTIN (for the tax invoice)\n  // Billing entity the client belongs to (WEB_SOLUTIONS | WEB_ROCZ | WEB_ROCZ_PVT) — lets a\n  // client show in that company's list before its first invoice exists. \"\" = from invoices only.\n  billingCompany     String   @default(\"\")\n  billingDay         Int      @default(0) // day of the month the invoice is raised (1..31); 0 = not set\n  paymentTerm        String   @default(\"\") // PREPAID | POSTPAID — ticked on the Web Rocz / Pvt Ltd client forms\n  importantNotes     String   @default(\"[]\") // JSON: [{date,time,by,note}] — important notes the accounts team keeps on the client\n  // --- Website renewal / hosting (one website per client) ---\n  websiteName        String   @default(\"\") // website URL\n  websiteDomain      String   @default(\"\") // e.g. example.com\n  websiteServices    String   @default(\"[]\") // JSON list of services (Domain / Hosting + SSL / Website Designing / custom)\n  domainTaken        Boolean  @default(false) // domain service taken\n  domainAmount       Int      @default(0) // INR — domain cost\n  hostingTaken       Boolean  @default(false) // hosting + SSL taken with us?\n  hostingAmount      Int      @default(0) // INR — hosting cost\n  designAmount       Int      @default(0) // INR — website designing (one-time) cost\n  websiteTakenDate   String   @default(\"\") // \"2026-01-15\" — when the website/hosting started\n  websiteExpiryDate  String   @default(\"\") // \"2027-01-15\" — renewal/expiry date\n  websiteRenewAmount Int      @default(0) // INR to renew the website/hosting\n  // --- Accountant follow-up log (client level): JSON [{ date, by, note, next }] ---\n  followupLog        String   @default(\"[]\")\n  nextFollowup       String   @default(\"\") // next planned follow-up date\n  notes              String?\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  accountManagerId String?\n  accountManager   User?   @relation(\"AccountManager\", fields: [accountManagerId], references: [id])\n\n  services        ClientService[]\n  deliverables    Deliverable[]\n  assignments     Assignment[]\n  updates         WorkUpdate[]\n  adsMetrics      AdsPerformance[]\n  invoices        Invoice[]\n  salesInvoices   SalesInvoice[]\n  slas            Sla[]\n  campaigns       CampaignEntry[]\n  socialPosts     SocialPost[]\n  devProjects     DevProject[]\n  contacts        ClientContact[]\n  tasks           Task[]\n  googleCampaigns GoogleAdsCampaign[]\n  creativeTasks   CreativeTask[]\n  seoAnalytics    SeoAnalytics[]\n  seoBlogSlots    SeoBlogSlot[]\n  seoKeywords     SeoKeyword[]\n  seoBacklinks    SeoBacklink[]\n  gmbLocations    GmbClient[]\n  seoReports      SeoReport[]\n  shoots          Shoot[]\n\n  @@index([status])\n  @@index([accountManagerId])\n}\n\nmodel ClientContact {\n  id       String  @id @default(cuid())\n  clientId String\n  client   Client  @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  name     String\n  role     String  @default(\"\") // Owner, Marketing Head, Finance, ...\n  phone    String  @default(\"\")\n  email    String  @default(\"\")\n  primary  Boolean @default(false)\n\n  @@index([clientId])\n}\n\n// Which services a client has taken (SEO, SMO, VIDEO, META_ADS, ...)\nmodel ClientService {\n  id       String  @id @default(cuid())\n  clientId String\n  client   Client  @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  service  String // see SERVICES in domain.ts\n  detail   String? // e.g. website type, branding requirements, \"other\" specify\n\n  @@unique([clientId, service])\n  @@index([clientId])\n}\n\n// Agreed monthly deliverable target per client + metric (blogs, keywords, static, reels...)\nmodel Deliverable {\n  id       String @id @default(cuid())\n  clientId String\n  client   Client @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  service  String // SEO | SMO | VIDEO | ...\n  metric   String // blogs | keywords | static | carousel | reels | aiVideos | reelsEdit\n  agreed   Int    @default(0)\n\n  @@unique([clientId, service, metric])\n  @@index([clientId])\n}\n\n// Team member assigned to a client for a department\nmodel Assignment {\n  id         String @id @default(cuid())\n  clientId   String\n  client     Client @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  userId     String\n  user       User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  department String // SEO | DESIGN | VIDEO | ACCOUNT | ADS\n\n  @@unique([clientId, userId, department])\n  @@index([clientId])\n  @@index([userId])\n}\n\n// Activity log — every unit of work, dated. Drives targets/reports.\nmodel WorkUpdate {\n  id        String   @id @default(cuid())\n  clientId  String\n  client    Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  date      DateTime @default(now())\n  workType  String // blog | keyword | static | carousel | reel | aiVideo | reelEdit | meeting | ...\n  quantity  Int      @default(1)\n  status    String   @default(\"COMPLETED\") // PLANNED | IN_PROGRESS | COMPLETED | APPROVED | PENDING_APPROVAL\n  title     String?\n  detail    String?\n  proofLink String?\n  notes     String?\n\n  // SEO-specific ranking fields\n  keyword      String?\n  prevPosition Int?\n  currPosition Int?\n  followUpDate DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([clientId])\n  @@index([userId])\n  @@index([date])\n}\n\n// Monthly invoice / payment per client — Super Admin billing only\nmodel Invoice {\n  id        String    @id @default(cuid())\n  clientId  String\n  client    Client    @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  number    String    @unique // INV-2026-08-0001\n  month     String // \"2026-08\"\n  amount    Int\n  status    String    @default(\"PENDING\") // PENDING | PAID | OVERDUE\n  paidAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@unique([clientId, month])\n  @@index([clientId])\n  @@index([month])\n}\n\n// One-time sales invoice generated when a lead is onboarded (printable + emailable).\n// Scalar refs only (no FK relations) to stay fully additive on db push.\nmodel SalesInvoice {\n  id            String    @id @default(cuid())\n  number        String    @unique // WR-INV-2026-0001\n  leadId        String?\n  clientId      String?\n  pipeline      String    @default(\"WEBROCZ\")\n  // Billing entity this invoice belongs to: WEB_SOLUTIONS | WEB_ROCZ | WEB_ROCZ_PVT\n  // (derived from GST + service at creation; drives the serial series & reports)\n  company       String    @default(\"\")\n  billTo        String // client / company name\n  contact       String?\n  phone         String?\n  email         String?\n  items         String    @default(\"[]\") // JSON: [{ name, qty, rate, amount }]\n  subtotal      Int       @default(0)\n  taxPct        Int       @default(18)\n  taxAmount     Int       @default(0)\n  total         Int       @default(0)\n  received      Int       @default(0)\n  paymentStatus String    @default(\"Pending\")\n  paymentProof  String    @default(\"\") // uploaded payment screenshot (Web Solutions new-invoice flow)\n  invoiceDoc    String    @default(\"\") // uploaded signed/printed invoice document (PDF/image)\n  // Web Rocz Pvt Ltd invoice form: the date the project started, and whether the client pays\n  // before the work (PREPAID) or after it (POSTPAID). \"\" = not set.\n  projectDate   String    @default(\"\") // \"2026-02-05\"\n  paymentTerm   String    @default(\"\") // PREPAID | POSTPAID\n  notes         String?\n  issueDate     String // \"2026-09-18\"\n  dueDate       String    @default(\"\") // \"2026-10-03\" — payment due date (Net-15 from issue by default)\n  // GST / client billing details (match the tax-invoice format)\n  clientGstin   String?\n  clientState   String?   @default(\"36-Telangana\")\n  clientAddress String?\n  placeOfSupply String?   @default(\"36-Telangana\")\n  // Super Admin approval gate — download only allowed once approved\n  approved      Boolean   @default(false)\n  approvedBy    String?\n  approvedAt    DateTime?\n  // Accountant follow-up log (visible to Super Admin): JSON [{ date, by, note }]\n  notesLog      String    @default(\"[]\")\n  nextFollowup  String?\n  emailedAt     DateTime?\n  createdAt     DateTime  @default(now())\n\n  payments Payment[]\n  // Client link: deleting a client removes its sales invoices (payments cascade in turn),\n  // matching the monthly Invoice model — prevents orphaned invoices in the finance reports.\n  client   Client?   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n\n  @@index([leadId])\n  @@index([clientId])\n}\n\n// Payment ledger — one row per collection against a SalesInvoice. The invoice's\n// `received` field is kept as the running total so existing reads stay unchanged.\nmodel Payment {\n  id        String       @id @default(cuid())\n  invoiceId String\n  invoice   SalesInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  amount    Int\n  date      String       @default(\"\") // \"2026-09-24\"\n  mode      String       @default(\"BANK\") // UPI | BANK | CHEQUE | CASH | CARD | OTHER\n  ref       String       @default(\"\") // txn id / cheque no / UTR\n  note      String       @default(\"\")\n  by        String       @default(\"\") // who recorded it\n  createdAt DateTime     @default(now())\n\n  @@index([invoiceId])\n  @@index([date])\n}\n\n// SLA (service agreement) uploaded by the sales team for a client. The accountant\n// reviews it and generates the invoice from its terms (service + amount + GST).\nmodel Sla {\n  id         String   @id @default(cuid())\n  clientName String   @default(\"\") // typed by sales (may or may not match an existing client)\n  clientId   String? // set when the typed name matches an existing client\n  client     Client?  @relation(fields: [clientId], references: [id], onDelete: SetNull)\n  title      String   @default(\"\") // e.g. \"Website + SEO annual SLA\"\n  service    String   @default(\"WEBSITE\") // WEBSITE | DM\n  amount     Int      @default(0) // agreed amount (before GST)\n  gst        Boolean  @default(false) // true = With GST 18%, false = Without GST\n  // Client details captured at upload so the accountant's invoice/filters are complete\n  // even when the SLA is for a brand-new client (no existing record to pull from).\n  pocName    String   @default(\"\") // contact person\n  pocMobile  String   @default(\"\") // phone\n  pocEmail   String   @default(\"\") // email\n  gstin      String   @default(\"\") // client GSTIN (for GST invoices / place of supply)\n  fileUrl    String   @default(\"\") // the uploaded SLA document\n  notes      String   @default(\"\")\n  status     String   @default(\"UPLOADED\") // UPLOADED | INVOICED\n  invoiceId  String? // the generated SalesInvoice, once created\n  uploadedBy String   @default(\"\") // sales person's name\n  createdAt  DateTime @default(now())\n\n  @@index([clientId])\n  @@index([status])\n}\n\n// Recruitment / hiring pipeline — candidates for employee positions (separate from sales).\nmodel Candidate {\n  id           String   @id @default(cuid())\n  code         String   @unique // CAND-0001\n  name         String\n  phone        String   @default(\"\")\n  email        String   @default(\"\")\n  position     String   @default(\"\") // role applying for\n  department   String   @default(\"\")\n  source       String   @default(\"\")\n  experience   String   @default(\"\")\n  expectedCtc  Int      @default(0)\n  resumeUrl    String   @default(\"\")\n  notes        String   @default(\"\")\n  notesLog     String   @default(\"[]\") // JSON: [{date, by, note}]\n  stage        String   @default(\"APPLIED\") // APPLIED | INTERVIEW | SHORTLISTED | OFFER | HIRED | REJECTED\n  rejectReason String   @default(\"\")\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([stage])\n}\n\n// Per-client, per-day Meta Ads campaign entry (AM daily update mode)\nmodel CampaignEntry {\n  id              String   @id @default(cuid())\n  clientId        String\n  client          Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  date            String // \"2026-08-27\"\n  type            String // LEAD | CALLS | WHATSAPP | AWARENESS | SALE\n  results         Int      @default(0) // leads / calls / whatsapp / reach / orders\n  spent           Int      @default(0)\n  conversions     Int      @default(0)\n  saleValue       Int      @default(0) // Sale campaigns only\n  ordersConverted Int      @default(0) // Sale campaigns only\n  updatedAt       DateTime @updatedAt\n\n  @@unique([clientId, date, type])\n  @@index([date])\n  @@index([clientId])\n}\n\nmodel DevProject {\n  id           String   @id @default(cuid())\n  name         String\n  clientId     String?\n  client       Client?  @relation(fields: [clientId], references: [id], onDelete: SetNull)\n  assignedToId String?\n  assignedTo   User?    @relation(\"DevAssignee\", fields: [assignedToId], references: [id], onDelete: SetNull)\n  projectType  String   @default(\"WEBSITE\") // WEBSITE | LANDING\n  platform     String   @default(\"WORDPRESS\") // WORDPRESS | SHOPIFY | REACT | NEXTJS | NODEJS | HTML\n  status       String   @default(\"PLANNING\") // PLANNING | IN_PROGRESS | REVIEW | LIVE | ON_HOLD\n  priority     String   @default(\"MEDIUM\") // HIGH | MEDIUM | LOW\n  progress     Int      @default(0) // 0-100\n  dueDate      String   @default(\"\") // \"2026-09-15\"\n  liveUrl      String   @default(\"\")\n  repoUrl      String   @default(\"\")\n  notes        String   @default(\"\")\n  shareId      String   @default(\"\")\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  tasks      DevTask[]\n  activities DevActivity[]\n\n  @@index([assignedToId])\n  @@index([status])\n  @@index([shareId])\n}\n\nmodel DevTask {\n  id        String     @id @default(cuid())\n  projectId String\n  project   DevProject @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  title     String\n  done      Boolean    @default(false)\n  slot      Int        @default(0)\n  createdAt DateTime   @default(now())\n\n  @@index([projectId])\n}\n\nmodel DevActivity {\n  id        String     @id @default(cuid())\n  projectId String\n  project   DevProject @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  actor     String     @default(\"\")\n  message   String\n  createdAt DateTime   @default(now())\n\n  @@index([projectId])\n  @@index([createdAt])\n}\n\nmodel SocialPost {\n  id        String   @id @default(cuid())\n  clientId  String\n  client    Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  date      String // \"2026-08-27\"\n  platform  String // INSTAGRAM | FACEBOOK | LINKEDIN | YOUTUBE\n  postType  String // POST | REEL | STORY | CAROUSEL\n  link      String   @default(\"\")\n  status    String   @default(\"SCHEDULED\") // POSTED | SCHEDULED\n  slot      Int      @default(0) // ordering within a client+platform\n  updatedAt DateTime @updatedAt\n\n  @@index([date])\n  @@index([clientId])\n}\n\n// Google Search Console + Google Analytics monthly numbers per SEO client.\nmodel SeoAnalytics {\n  id              String @id @default(cuid())\n  clientId        String\n  client          Client @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  month           String // \"2026-08\"\n  gscClicks       Int    @default(0)\n  gscImpressions  Int    @default(0)\n  gscCtr          Float  @default(0) // %\n  gscPosition     Float  @default(0) // avg position\n  gaUsers         Int    @default(0) // active users\n  gaNewUsers      Int    @default(0)\n  gaOrganic       Int    @default(0) // organic search users\n  gaOrganicSocial Int    @default(0) // organic social users\n  gaSessions      Int    @default(0)\n  gaBounce        Float  @default(0) // %\n  gaEngagement    String @default(\"\") // avg engagement time \"2m 34s\"\n  gaConversions   Int    @default(0)\n\n  @@unique([clientId, month])\n  @@index([clientId])\n}\n\n// Blogs Report tracker — 8 slots per client per month, each slot has 3 stages\n// (Blog written · Image done · Website live). Mirrors the \"Blogs Report Data\" tab.\nmodel SeoBlogSlot {\n  id        String   @id @default(cuid())\n  clientId  String\n  client    Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  month     String // \"2026-08\"\n  slot      Int // 1..N (week·position, e.g. 1 = W1·1)\n  writer    String   @default(\"\") // blog writer name (Shruthi, Sneha, Bhavani, ...)\n  blog      String   @default(\"PENDING\") // PENDING | REVIEW | PUBLISHED  (Draft | Pending Review | Published)\n  image     String   @default(\"PENDING\") // PENDING | DONE\n  web       String   @default(\"PENDING\") // PENDING | LIVE\n  title     String   @default(\"\")\n  link      String   @default(\"\")\n  blogDate  String   @default(\"\") // \"2026-08-14\"\n  updatedAt DateTime @updatedAt\n\n  @@unique([clientId, month, slot])\n  @@index([clientId, month])\n}\n\n// Per-client monthly keyword position tracking (mirrors the dashboard Keywords tab).\nmodel SeoKeyword {\n  id        String   @id @default(cuid())\n  clientId  String\n  client    Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  month     String // \"2026-08\"\n  slot      Int      @default(0)\n  keyword   String   @default(\"\")\n  lastPos   Int      @default(0)\n  currPos   Int      @default(0)\n  updatedAt DateTime @updatedAt\n\n  @@index([clientId, month])\n}\n\n// Per-client monthly backlinks (mirrors the dashboard Backlinks tab).\nmodel SeoBacklink {\n  id        String   @id @default(cuid())\n  clientId  String\n  client    Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  month     String // \"2026-08\"\n  slot      Int      @default(0)\n  type      String   @default(\"Guest Post\")\n  status    String   @default(\"Live\") // Live | Pending | Removed\n  link      String   @default(\"\")\n  da        Int      @default(0) // domain authority\n  date      String   @default(\"\")\n  updatedAt DateTime @updatedAt\n\n  @@index([clientId, month])\n}\n\n// Local SEO / Google Business Profile — one row per GMB location (a client can\n// have several). Mirrors the \"Local SEO (GMB) Clients\" tab.\nmodel GmbClient {\n  id           String   @id @default(cuid())\n  name         String\n  clientId     String?\n  client       Client?  @relation(fields: [clientId], references: [id], onDelete: SetNull)\n  assigned     String   @default(\"\") // GMB owner (Kishore, Veni, Sowji, ...)\n  gmbLink      String   @default(\"\")\n  monthlyPosts Int      @default(0) // target posts / month\n  postsDone    Int      @default(0)\n  lastPostDate String   @default(\"\")\n  citations    Int      @default(0)\n  reviews      Int      @default(0)\n  reviewsNote  String   @default(\"\") // \"No commitment\" / \"10\" ...\n  localo       Boolean  @default(false)\n  active       Boolean  @default(true)\n  updatedAt    DateTime @updatedAt\n\n  @@index([assigned])\n  @@index([clientId])\n}\n\n// Monthly report delivery — mirrors the \"SEO Reports Data\" tab.\nmodel SeoReport {\n  id            String   @id @default(cuid())\n  clientId      String\n  client        Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  month         String // \"2026-08\"\n  reportDate    String   @default(\"\") // \"10th\" / \"1st\"\n  status        String   @default(\"PENDING\") // SENT | PENDING\n  gscDone       Boolean  @default(false)\n  gaDone        Boolean  @default(false)\n  assigned      String   @default(\"\") // who prepares the report\n  keywordStatus String   @default(\"\") // Done | Pending\n  note          String   @default(\"\")\n  updatedAt     DateTime @updatedAt\n\n  @@unique([clientId, month])\n  @@index([clientId])\n}\n\n// Creative task board — one row per design / video assigned to a designer or editor.\nmodel CreativeTask {\n  id             String   @id @default(cuid())\n  kind           String // DESIGN | VIDEO\n  code           String // DSG-001 / VID-001\n  title          String\n  clientId       String?\n  client         Client?  @relation(fields: [clientId], references: [id], onDelete: SetNull)\n  assignedToId   String\n  assignedTo     User     @relation(\"CreativeAssignee\", fields: [assignedToId], references: [id], onDelete: Cascade)\n  assignedById   String?\n  assignedByUser User?    @relation(\"CreativeAssigner\", fields: [assignedById], references: [id], onDelete: SetNull)\n  type           String // Logo|Social Creative|... (design) or Testimonial|Reel|YouTube|Intro|Ad Video (video)\n  priority       String   @default(\"MEDIUM\") // HIGH | MEDIUM | LOW\n  status         String   @default(\"PENDING\") // PENDING | IN_PROGRESS | REVIEW | COMPLETED\n  source         String   @default(\"ONBOARDING\") // ONBOARDING | ADDITIONAL\n  assignedDate   String   @default(\"\") // \"2026-08-24\"\n  dueDate        String   @default(\"\") // \"2026-08-27\"\n  dimensions     String   @default(\"\") // \"1080×1080 px\" / duration\n  brief          String   @default(\"\")\n  notes          String   @default(\"\")\n  refLink        String   @default(\"\")\n  rawLink        String   @default(\"\")\n  finalLink      String   @default(\"\")\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@index([assignedToId])\n  @@index([kind])\n  @@index([status])\n}\n\n// Shooting & Studio X: in-house WebRocz client shoots + paid Studio X rentals.\n// Raj (Studio X Head) / admins schedule and assign; Mallesh (Videographer) shoots.\nmodel Shoot {\n  id            String   @id @default(cuid())\n  code          String // SHT-001\n  category      String // WEBROCZ | STUDIO_RENT\n  title         String\n  clientId      String? // set for WebRocz client shoots\n  client        Client?  @relation(fields: [clientId], references: [id], onDelete: SetNull)\n  renterName    String   @default(\"\") // renter / contact name (esp. Studio X rent)\n  phone         String   @default(\"\")\n  date          String // \"2026-10-05\"\n  startTime     String   @default(\"\") // \"10:00\"\n  endTime       String   @default(\"\") // \"13:00\"\n  locationType  String   @default(\"IN_HOUSE\") // IN_HOUSE (Studio X) | ON_LOCATION (client's place)\n  location      String   @default(\"\") // address / details\n  assignedToId  String? // the shooter (Mallesh)\n  assignedTo    User?    @relation(\"ShootAssignee\", fields: [assignedToId], references: [id], onDelete: SetNull)\n  status        String   @default(\"SCHEDULED\") // SCHEDULED | IN_PROGRESS | COMPLETED | CANCELLED\n  rentAmount    Int      @default(0) // ₹ for Studio X rentals\n  paid          Boolean  @default(false)\n  notes         String   @default(\"\")\n  requestedById String? // an AM who requested this WebRocz shoot (Raj then assigns a shooter)\n  requestedBy   User?    @relation(\"ShootRequester\", fields: [requestedById], references: [id], onDelete: SetNull)\n  footageLink   String   @default(\"\") // raw footage drive link after the shoot\n  handedOff     Boolean  @default(false) // handed to a video editor\n  followupLog   String   @default(\"[]\") // JSON: [{date,time,by,note,via}] — Phone / WhatsApp follow-ups on this shoot\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([date])\n  @@index([assignedToId])\n  @@index([category])\n}\n\n// Google Ads — one row per campaign per client per day (daily-entry AM workflow)\nmodel GoogleAdsCampaign {\n  id          String   @id @default(cuid())\n  clientId    String\n  client      Client   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  date        String // \"2026-08-30\"\n  name        String // \"Search - Skin Treatment\"\n  type        String // SEARCH | DISPLAY | PMAX | SMART\n  spent       Int      @default(0)\n  leads       Int      @default(0)\n  conversions Int      @default(0)\n  status      String   @default(\"ACTIVE\") // ACTIVE | PAUSED\n  updatedBy   String   @default(\"\")\n  updatedAt   DateTime @updatedAt\n\n  @@index([date])\n  @@index([clientId])\n}\n\n// Monthly ads numbers per client — entered separately from onboarding\nmodel AdsPerformance {\n  id          String @id @default(cuid())\n  clientId    String\n  client      Client @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  month       String // \"2026-08\"\n  platform    String // META | GOOGLE\n  spend       Int    @default(0)\n  leads       Int    @default(0)\n  clicks      Int    @default(0)\n  impressions Int    @default(0)\n  conversions Int    @default(0)\n  ctr         Float  @default(0)\n  cpl         Float  @default(0)\n\n  @@unique([clientId, month, platform])\n  @@index([clientId])\n}\n\n// In-app notification — one row per recipient per event (client onboarding assignment,\n// a creative task assigned by an Account Manager, etc.). Kept lightweight: no FK relation\n// so it can be written from any action without touching the User model.\nmodel Notification {\n  id        String   @id @default(cuid())\n  userId    String // recipient\n  title     String\n  body      String   @default(\"\")\n  link      String   @default(\"/\")\n  tone      String   @default(\"violet\") // violet | rose | amber | emerald\n  read      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@index([userId, read])\n  @@index([createdAt])\n}\n\n// ============================================================\n//  SALES CRM — pipeline: Positive Lead → … → Onboarded / Lost\n// ============================================================\nmodel Lead {\n  id            String   @id @default(cuid())\n  code          String   @unique // LEAD-0001\n  pipeline      String   @default(\"WEBROCZ\") // WEBROCZ | DIGITALHAT — separate sales pipelines\n  name          String\n  company       String   @default(\"\")\n  contactPerson String   @default(\"\")\n  phone         String   @default(\"\")\n  whatsapp      String   @default(\"\")\n  email         String   @default(\"\")\n  source        String   @default(\"\")\n  services      String   @default(\"\") // JSON array of service names (multi-select)\n  value         Int      @default(0) // expected budget (INR)\n  stage         String   @default(\"POSITIVE_LEAD\")\n  assignedToId  String?\n  assignedTo    User?    @relation(\"LeadOwner\", fields: [assignedToId], references: [id], onDelete: SetNull)\n  notes         String   @default(\"\")\n  // Interested stage\n  requirements  String   @default(\"\")\n  budget        Int      @default(0)\n  expectedStart String   @default(\"\")\n  decisionMaker String   @default(\"\")\n  timeline      String   @default(\"\")\n  nextAction    String   @default(\"\")\n  // Lost stage\n  lostReason    String   @default(\"\")\n  lostNotes     String   @default(\"\")\n  lostDate      String   @default(\"\")\n  // Onboarding link — a Lead becomes a single Client on onboard (no duplicate clients)\n  clientId      String?\n  paymentStatus String   @default(\"\")\n  startDate     String   @default(\"\")\n  finalAmount   Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  followups  Followup[]\n  quotations Quotation[]\n  proposals  Proposal[]\n  reminders  Reminder[]\n  meetings   Meeting[]\n  activities LeadActivity[]\n\n  @@index([stage])\n  @@index([assignedToId])\n  @@index([pipeline])\n}\n\nmodel LeadActivity {\n  id        String   @id @default(cuid())\n  leadId    String\n  lead      Lead     @relation(fields: [leadId], references: [id], onDelete: Cascade)\n  actor     String   @default(\"\")\n  action    String\n  detail    String   @default(\"\")\n  createdAt DateTime @default(now())\n\n  @@index([leadId])\n}\n\nmodel Followup {\n  id        String   @id @default(cuid())\n  leadId    String\n  lead      Lead     @relation(fields: [leadId], references: [id], onDelete: Cascade)\n  date      String   @default(\"\") // \"2026-09-20\"\n  time      String   @default(\"\")\n  type      String   @default(\"Call\")\n  notes     String   @default(\"\")\n  nextDate  String   @default(\"\")\n  nextTime  String   @default(\"\")\n  status    String   @default(\"PENDING\") // PENDING | COMPLETED | RESCHEDULED | NO_RESPONSE\n  createdAt DateTime @default(now())\n\n  @@index([leadId])\n  @@index([status])\n  @@index([date])\n}\n\nmodel Quotation {\n  id          String   @id @default(cuid())\n  leadId      String\n  lead        Lead     @relation(fields: [leadId], references: [id], onDelete: Cascade)\n  number      String   @default(\"\")\n  services    String   @default(\"\")\n  amount      Int      @default(0)\n  tax         Int      @default(0)\n  finalAmount Int      @default(0)\n  date        String   @default(\"\")\n  validUntil  String   @default(\"\")\n  fileUrl     String   @default(\"\")\n  status      String   @default(\"DRAFT\")\n  createdAt   DateTime @default(now())\n\n  @@index([leadId])\n}\n\nmodel Proposal {\n  id           String   @id @default(cuid())\n  leadId       String\n  lead         Lead     @relation(fields: [leadId], references: [id], onDelete: Cascade)\n  number       String   @default(\"\")\n  fileUrl      String   @default(\"\")\n  sharedDate   String   @default(\"\")\n  amount       Int      @default(0)\n  expectedDate String   @default(\"\")\n  notes        String   @default(\"\")\n  status       String   @default(\"SHARED\")\n  createdAt    DateTime @default(now())\n\n  @@index([leadId])\n}\n\nmodel Reminder {\n  id         String   @id @default(cuid())\n  leadId     String\n  lead       Lead     @relation(fields: [leadId], references: [id], onDelete: Cascade)\n  date       String   @default(\"\")\n  time       String   @default(\"\")\n  type       String   @default(\"Call\")\n  notes      String   @default(\"\")\n  nextAction String   @default(\"\")\n  status     String   @default(\"PENDING\")\n  createdAt  DateTime @default(now())\n\n  @@index([leadId])\n  @@index([status])\n}\n\nmodel Meeting {\n  id         String   @id @default(cuid())\n  leadId     String\n  lead       Lead     @relation(fields: [leadId], references: [id], onDelete: Cascade)\n  type       String   @default(\"ONLINE\") // OFFICE_VISIT | CLIENT_LOCATION | ONLINE\n  date       String   @default(\"\")\n  time       String   @default(\"\")\n  person     String   @default(\"\")\n  link       String   @default(\"\")\n  location   String   @default(\"\")\n  notes      String   @default(\"\")\n  outcome    String   @default(\"\")\n  nextAction String   @default(\"\")\n  createdAt  DateTime @default(now())\n\n  @@index([leadId])\n  @@index([date])\n}\n\n// Business expense — powers company-wise Profit & Loss (income − expenses).\nmodel Expense {\n  id        String   @id @default(cuid())\n  company   String   @default(\"\") // WEB_SOLUTIONS | WEB_ROCZ | WEB_ROCZ_PVT | \"\" = general/shared\n  category  String   @default(\"\") // Salaries | Ads Spend | Tools/Software | Rent | Utilities | Marketing | Misc\n  vendor    String   @default(\"\") // who it was paid to\n  amount    Int      @default(0)\n  date      String   @default(\"\") // \"2026-09-15\"\n  notes     String   @default(\"\")\n  by        String   @default(\"\") // who recorded it\n  createdAt DateTime @default(now())\n\n  @@index([company])\n  @@index([date])\n}\n"
}

